#!/usr/bin/env node
/**
 * PHASE 10 - MULTIPLE SLOTS + INSTALLABLE PWA + OMNI FLOW API
 * ===========================================================
 * Phase 9 made the claims automatic. This phase makes the product bigger in three directions at once,
 * and each one is useful on its own:
 *
 *  1. MORE THAN ONE POST A DAY. Publish slots (1-5) instead of one time. Every slot claims its own topic,
 *     drafts its own post, gets its own approval email and publishes at its own time. Slot 0 is exactly
 *     the old behaviour, so an owner who never adds a second slot sees no change at all.
 *  2. AN INSTALLABLE APP. Manifest + service worker + icons, so the dashboard lives on a phone home
 *     screen, and web push tells the owner when a draft is ready, a publish failed, or an approval link
 *     is about to die. Without VAPID keys the UI says push is not configured - it never fakes a send.
 *  3. AN API FOR OTHER TOOLS. `opk_` keys stored as a sha256 hash + prefix, scoped read/write/publish,
 *     immediate revocation, and HMAC-signed webhooks with a delivery log, backoff retries and an
 *     endpoint that switches itself off after five consecutive failures.
 *
 * WHAT IS IN THE BOX
 *   New files
 *     supabase/migrations/0005_slots_and_api.sql   slots, claims, api_keys, webhooks, push devices
 *     src/core/omni.ts            keys, signing, envelope, retry policy, delivery loop
 *     src/core/omni-dispatch.ts   the wiring between the core and the database port
 *     src/core/push.ts            subscription parsing, notification wording, broadcast + retire
 *     src/core/push-send.ts       VAPID config, the fetch sender, "not configured" honesty
 *     src/worker/middleware/api-key.ts, routes/omni.ts, routes/push.ts
 *     components/pwa-bridge.tsx   service-worker registration + the notifications card
 *     components/settings/api-panel.tsx   keys and webhooks, secrets shown once
 *     public/manifest.webmanifest, public/sw.js, public/icons/*.png
 *     tests/slots.test.ts, tests/omni.test.ts, tests/push.test.ts, e2e/phase10.spec.ts
 *     docs/API.md, plus a Phase 10 section in TESTING.md / SETUP.md / ROADMAP.md
 *   Edits (anchored, never whole-file)
 *     types, ports, defaults, services, schedule, scheduler, generation, publishing, approval,
 *     both database adapters, env config, worker app + schemas, dashboard settings page + layout,
 *     lib/types, the shared test harness, e2e fixtures.
 *
 * HOW IT TREATS YOUR FILES  (same contract as Phase 9 v2)
 * ------------------------------------------------------
 *   - New files are full payloads. An existing file with different content is SKIPPED with the reason
 *     and never overwritten.
 *   - Existing files get small anchored EDITS. Anchors are matched on CRLF-normalised text, so a
 *     Windows checkout matches, and each file keeps its own line endings.
 *   - An edit that cannot be found, or that is ambiguous, is SKIPPED and listed. It never blocks the
 *     rest of the patch, and re-running is safe: everything already applied counts as done.
 *   - Nothing is deleted, no `.bak` files, and every write is verified against the plan before it lands.
 *   - `package.json` is merged, not overwritten: this phase adds no scripts, it only grows the project.
 *
 * Usage (project root, next to package.json):
 *
 *   node phase10.mjs --dry-run    # show every change, write nothing
 *   node phase10.mjs              # apply what is missing, skip what does not fit
 *   node phase10.mjs --check      # apply, then typecheck + UI guard + unit tests
 *   node phase10.mjs --version    # patch fingerprint
 *
 * After applying, database work is one command:
 *   Supabase -> SQL Editor -> run supabase/migrations/0005_slots_and_api.sql (or `supabase db push`)
 *
 * Generated 2026-11-19 - 22 new files, 52 edits across 28 files.
 */
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const PHASE = 'phase10';
const ROOT = dirname(fileURLToPath(import.meta.url));
const argv = process.argv.slice(2);
const dryRun = argv.includes('--dry-run');
const runChecks = argv.includes('--check');

const normalise = (text) => text.replace(/\r\n/g, '\n');
const short = (text) => createHash('sha256').update(normalise(text)).digest('hex').slice(0, 12);
/** Binary payloads (the PWA icons) travel as base64 and are compared on their raw bytes. */
const shortBytes = (buffer) => createHash('sha256').update(buffer).digest('hex').slice(0, 12);

/** Files this phase creates. An existing copy with the same hash is "already done". */
